"""Edge-case tests for marks-rendering (Round 2) -- generated by bug-hunter agent.

Focus areas:
- Annotation mark rendering edge cases (annotate_hline at domain edges, etc.)
- configure() interactions with mark styling (axis title color, font-size)
- Format presets system (resolve_format, unknown presets, preset round-trip via AxisConfig)
- Structural features: SecondaryY, BreakAxis, Inset validation
- Axis title color/font-size fields in AxisConfig/TitleConfig
- Mark rendering corner cases not covered in Round 1
- Cross-mark composition: layer + configure + theme stacking
"""

from __future__ import annotations
import re

import pytest
import polars as pl
import ferrum as fr


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _has_nan_in_svg(svg: str) -> bool:
    """Check if SVG contains NaN in any attribute value."""
    return "NaN" in svg


def _has_infinity_in_svg(svg: str) -> bool:
    """Check if SVG contains Infinity in any attribute value."""
    return "Infinity" in svg


def _count_tag(svg: str, tag: str) -> int:
    """Count occurrences of a specific SVG tag."""
    return svg.count(f"<{tag}")


# ---------------------------------------------------------------------------
# 1. Format presets system (targets format_presets.py resolve_format)
# ---------------------------------------------------------------------------


def test_resolve_format_unknown_preset_raises_valueerror():
    """resolve_format('not_a_preset') must raise ValueError with a legible message.
    Targets format_presets.py line 66-69: the KeyError->ValueError conversion."""
    from ferrum.format_presets import resolve_format

    with pytest.raises(ValueError, match="Unknown format preset"):
        resolve_format("nonexistent_preset_name")


def test_resolve_format_all_numeric_presets_return_strings():
    """Every numeric preset key in NUMERIC_PRESETS must resolve to a non-empty string.
    Targets format_presets.py NUMERIC_PRESETS dict completeness."""
    from ferrum.format_presets import NUMERIC_PRESETS, resolve_format

    for key in NUMERIC_PRESETS:
        result = resolve_format(key)
        assert isinstance(result, str), f"preset {key!r} did not return str"
        assert len(result) > 0, f"preset {key!r} returned empty string"


def test_resolve_format_all_time_presets_return_strings():
    """Every time preset key in TIME_PRESETS must resolve to a non-empty string.
    Targets format_presets.py TIME_PRESETS dict completeness."""
    from ferrum.format_presets import TIME_PRESETS, resolve_format

    for key in TIME_PRESETS:
        result = resolve_format(key)
        assert isinstance(result, str), f"preset {key!r} did not return str"
        assert len(result) > 0, f"preset {key!r} returned empty string"


def test_is_time_preset_returns_false_for_numeric():
    """is_time_preset must return False for numeric presets and True for time presets.
    Targets format_presets.py is_time_preset line 92."""
    from ferrum.format_presets import is_time_preset

    assert is_time_preset("date_iso") is True
    assert is_time_preset("percent") is False
    assert is_time_preset("nonexistent") is False


def test_axis_config_label_format_preset_resolves_on_construction():
    """AxisConfig with label_format=<valid preset> must not raise.
    AxisConfig with label_format=<invalid preset> must raise ValueError.
    Targets configure.py AxisConfig.__post_init__ line 116."""
    # Valid preset
    config = fr.configure.AxisConfig(label_format="percent")
    d = config.to_dict()
    assert d["label_format"] == ".1%", f"expected '.1%', got {d['label_format']!r}"

    # Invalid preset
    with pytest.raises(ValueError, match="Unknown format preset"):
        fr.configure.AxisConfig(label_format="bogus_preset")


def test_axis_config_label_format_and_raw_mutually_exclusive():
    """AxisConfig with both label_format and label_format_raw must raise ValueError.
    Targets configure.py AxisConfig.__post_init__ line 110-114."""
    with pytest.raises(ValueError, match="mutually exclusive"):
        fr.configure.AxisConfig(label_format="percent", label_format_raw=".2f")


# ---------------------------------------------------------------------------
# 2. AxisConfig title_color / title_font_size fields
# ---------------------------------------------------------------------------


def test_axis_config_title_color_propagates_to_svg():
    """AxisConfig(title_color=...) must affect the axis title text color in SVG.
    Targets configure.py AxisConfig.title_color field and its propagation to
    the ThemeInputs -> axis.rs build_axis -> title text color path."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x=fr.X("x", axis=fr.Axis(title="Custom X")), y="y")
        .configure(axis=fr.configure.AxisConfig(title_color="#ff00ff"))
        .show_svg()
    )
    assert "NaN" not in svg
    # The title text should be rendered somewhere
    assert "Custom X" in svg


def test_axis_config_title_font_size_propagates():
    """AxisConfig(title_font_size=...) should not crash and produce valid SVG.
    Targets configure.py AxisConfig.title_font_size field serialization path."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x=fr.X("x", axis=fr.Axis(title="Big Title")), y="y")
        .configure(axis=fr.configure.AxisConfig(title_font_size=20.0))
        .show_svg()
    )
    assert svg.startswith("<svg")
    assert "NaN" not in svg
    assert "Big Title" in svg


