def test_break_axis_invalid_axis_raises():
    """BreakAxis(axis='z') must raise ValueError.
    Targets structural.py BreakAxis.__post_init__ line 65."""
    with pytest.raises(ValueError, match="must be 'x' or 'y'"):
        fr.BreakAxis(axis="z", gap=(10, 20))


def test_break_axis_invalid_style_raises():
    """BreakAxis(break_style='invalid') must raise ValueError.
    Targets structural.py BreakAxis.__post_init__ line 67-70."""
    with pytest.raises(ValueError, match="break_style must be one of"):
        fr.BreakAxis(axis="x", gap=(10, 20), break_style="invalid_style")


def test_break_axis_valid_styles_accepted():
    """All valid break styles must be accepted without error.
    Targets structural.py _VALID_BREAK_STYLES frozenset."""
    for style in ("slash", "zigzag", "wave", "gap"):
        ba = fr.BreakAxis(axis="y", gap=(10, 20), break_style=style)
        assert ba.break_style == style


def test_inset_invalid_connect_style_raises():
    """Inset(connect_style='bad') must raise ValueError.
    Targets structural.py Inset.__post_init__ line 115-119."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match="connect_style must be one of"):
        fr.Inset(chart=chart, bounds=(0, 0, 1, 1), connect_style="arrows")


def test_inset_valid_connect_styles_accepted():
    """All valid Inset connect styles must be accepted.
    Targets structural.py _VALID_CONNECT_STYLES frozenset."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y")
    for style in ("bracket", "lines", "none"):
        inset = fr.Inset(chart=chart, bounds=(0, 0, 1, 1), connect_style=style)
        assert inset.connect_style == style


def test_secondary_y_construction():
    """SecondaryY dataclass must accept all documented parameters.
    Targets structural.py SecondaryY.__init__ fields."""
    sy = fr.SecondaryY(field="revenue", mark="line", color="#ff0000", opacity=0.8)
    assert sy.field == "revenue"
    assert sy.mark == "line"
    assert sy.color == "#ff0000"
    assert sy.opacity == 0.8


