def test_configure_with_all_subconfigs_no_crash():
    """configure() with every sub-config set should not crash during rendering.
    Targets configure.py Configure.to_dict and the full config propagation pipeline."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure(
            axis=fr.configure.AxisConfig(label_angle=-30, tick_count=5),
            legend=fr.configure.LegendConfig(orient="right"),
            title=fr.configure.TitleConfig(font_size=18, anchor="start"),
            grid=fr.configure.GridConfig(x=True, y=True, color="#eeeeee"),
            padding=fr.configure.PaddingConfig(top=20, right=20, bottom=20, left=20),
        )
        .show_svg()
    )
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_configure_axis_x_overrides_axis():
    """axis_x should override axis for x-axis specific settings.
    Targets configure.py Configure fields axis vs axis_x precedence."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [10.0, 20.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure(
            axis=fr.configure.AxisConfig(label_font_size=10),
            axis_x=fr.configure.AxisConfig(label_font_size=16),
        )
        .show_svg()
    )
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_theme_and_configure_together_no_crash():
    """Using both .theme() and .configure() on the same chart must not crash.
    Tests the merge logic for theme + config overrides."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .theme(fr.Theme(mark_color="#00ff00", font_family="monospace"))
        .configure(axis=fr.configure.AxisConfig(label_angle=-45, grid=True))
        .show_svg()
    )
    assert svg.startswith("<svg")
    assert "NaN" not in svg
    # Theme mark_color should propagate
    assert "00ff00" in svg.lower()


