    df = pl.DataFrame(
        {
            "x": [1.0, 2.0],
            "y": [1.0, 2.0],
            "url": ["", ""],
        }
    )
    # This should not crash; empty URLs should be silently skipped
    svg = fr.Chart(df).mark_image().encode(x="x", y="y", url="url").show_svg()
    assert svg.startswith("<svg")
    assert "NaN" not in svg


