# ---------------------------------------------------------------------------
# 21. Configure serialization: to_dict omits None
# ---------------------------------------------------------------------------


def test_configure_to_dict_omits_none():
    """Configure.to_dict() must omit all None fields recursively.
    Targets configure.py _to_dict_omit_none helper."""
    cfg = fr.configure.Configure(
        axis=fr.configure.AxisConfig(label_angle=-45),
        # legend, title, grid, padding all None -> omitted
    )
    d = cfg.to_dict()
    assert "axis" in d
    assert "legend" not in d
    assert "title" not in d
    assert d["axis"]["label_angle"] == -45
    # Fields within AxisConfig that are None should also be omitted
    assert "grid_color" not in d["axis"]


# ---------------------------------------------------------------------------
# 22. Mixed null in multiple encoding channels simultaneously
# ---------------------------------------------------------------------------


def test_point_null_in_x_y_color_simultaneously():
    """Null in x, y, and color columns at different rows should render only
    fully-valid rows. Targets point.rs per-row skip + color fallback."""
    df = pl.DataFrame(
        {
            "x": [1.0, None, 3.0, 4.0],
            "y": [10.0, 20.0, None, 40.0],
            "c": ["red", "blue", "green", None],
        }
    )
    svg = fr.Chart(df).mark_point().encode(x="x", y="y", color="c:N").show_svg()
    assert svg.startswith("<svg")
    assert "NaN" not in svg
    # Rows 0 and 3 have valid x+y (row 3 has null color -> falls to default)
    # Row 1 has null x, row 2 has null y -> both skipped
    # So we expect at least 2 circles (+ legend glyphs)


