# ---------------------------------------------------------------------------


def test_padding_config_zero_on_all_sides():
    """PaddingConfig with all zeros should not crash (zero padding).
    Targets configure.py PaddingConfig fields."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(x="x", y="y")
        .configure(padding=fr.configure.PaddingConfig(top=0, right=0, bottom=0, left=0))
        .show_svg()
    )
    assert svg.startswith("<svg")
    assert "NaN" not in svg


def test_padding_config_very_large_values_raises():
    """PaddingConfig with padding exceeding viewport dimensions must raise ValueError.
    Targets layout.rs padding validation: padding that would leave no plot area."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    with pytest.raises(ValueError, match="padding.*exceeds"):
        (
            fr.Chart(df)
            .mark_point()
            .encode(x="x", y="y")
            .configure(padding=fr.configure.PaddingConfig(top=500, right=500, bottom=500, left=500))
            .show_svg()
        )


